const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Keechelus Lake geometry (approximate center and buffer)
  const keechelus = ee.Geometry.Point([-121.3514, 47.2947]).buffer(2000);

  // 2. Date ranges
  const date2024Start = '2024-07-01';
  const date2024End = '2024-07-31';
  const date2025Start = '2025-07-01';
  const date2025End = '2025-07-31';

  // 3. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 4. Water detection function using MNDWI
  function addWater(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('water');
    const waterMask = mndwi.gt(0);
    return image.addBands(waterMask);
  }

  // 5. Get Sentinel-2 data for July 2024
  let col2024 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(keechelus)
    .filterDate(date2024Start, date2024End)
    .map(maskS2clouds)
    .map(addWater);

  const size2024 = col2024.size().getInfo();
  console.log(`July 2024 images found: ${size2024}`);

  if (size2024 === 0) {
    console.log('No Sentinel-2 data for July 2024');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Get Sentinel-2 data for July 2025
  let col2025 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(keechelus)
    .filterDate(date2025Start, date2025End)
    .map(maskS2clouds)
    .map(addWater);

  const size2025 = col2025.size().getInfo();
  console.log(`July 2025 images found: ${size2025}`);

  if (size2025 === 0) {
    console.log('No Sentinel-2 data for July 2025');
    console.log('<answer>C1</answer>');
    return;
  }

  // 7. Create composite and calculate water extent
  const water2024 = col2024.select('water').median();
  const water2025 = col2025.select('water').median();

  // 8. Calculate statistics
  const stats2024 = water2024.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: keechelus,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels2024 = stats2024.water_sum || 0;
  const validPixels2024 = stats2024.water_count || 0;

  console.log(`2024: Water pixels = ${waterPixels2024}, Valid pixels = ${validPixels2024}`);

  if (validPixels2024 === 0) {
    console.log('No valid pixels for July 2024 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  const stats2025 = water2025.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: keechelus,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels2025 = stats2025.water_sum || 0;
  const validPixels2025 = stats2025.water_count || 0;

  console.log(`2025: Water pixels = ${waterPixels2025}, Valid pixels = ${validPixels2025}`);

  if (validPixels2025 === 0) {
    console.log('No valid pixels for July 2025 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 9. Check for calculation failures
  if (waterPixels2024 === null || waterPixels2025 === null) {
    console.log('Calculation returned null values');
    console.log('<answer>C3</answer>');
    return;
  }

  // 10. Compare water extent
  const decrease = waterPixels2025 < waterPixels2024;
  const percentChange = ((waterPixels2025 - waterPixels2024) / waterPixels2024 * 100).toFixed(2);

  console.log(`Change: ${percentChange}% (${waterPixels2024} -> ${waterPixels2025} pixels)`);

  if (decrease) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
